"use client";

import { ProductsTable } from "@/features/products/components/ProductsTable";
import { useProducts } from "@/features/products/useProducts";
import { useProductSelection } from "@/contexts/ProductSelectionContext";

export default function ProductsPage() {
  const { data: products = [], isLoading, error } = useProducts();
  const { selectProduct, selectedProduct, selectedSize } = useProductSelection();

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <p className="text-gray-500">読み込み中...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-semibold">商品データベース</h1>
        <div className="p-4 bg-red-50 border border-red-200 rounded-md">
          <p className="text-red-800 font-medium">エラーが発生しました</p>
          <p className="text-red-600 text-sm mt-1">
            {error instanceof Error ? error.message : "商品データの取得に失敗しました"}
          </p>
          <p className="text-red-600 text-sm mt-2">
            データベースに接続できているか、環境変数が正しく設定されているか確認してください。
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-semibold">商品データベース</h1>
      {products.length === 0 ? (
        <div className="p-4 bg-blue-50 border border-blue-200 rounded-md">
          <p className="text-blue-800 font-medium">商品が登録されていません</p>
          <p className="text-blue-600 text-sm mt-1">
            右上の「商品を追加」ボタンから商品を追加してください。
          </p>
        </div>
      ) : (
        <ProductsTable
          products={products}
          onProductSelect={selectProduct}
          selectedProductId={selectedProduct?.id}
          selectedSize={selectedSize}
        />
      )}
    </div>
  );
}
